package com.saleh.enezi;

import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity{
 static final int GREEN=Color.rgb(30,107,56),GOLD=Color.rgb(230,161,0),BLUE=Color.rgb(42,82,190),RED=Color.rgb(229,57,53);
 DB db;LinearLayout root,content,bottom;int textSize=17;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(21,85,45));db=new DB(this);home();}
 TextView tv(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.rgb(35,45,38));v.setPadding(18,14,18,14);return v;}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setPadding(12,4,12,4);return b;}
 EditText field(String h){EditText e=new EditText(this);e.setHint(h);e.setTextSize(textSize);e.setSingleLine(true);e.setPadding(16,8,16,8);e.setBackgroundColor(Color.WHITE);return e;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(247,249,247));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);bar.setPadding(12,4,12,4);bar.setBackgroundColor(GREEN);TextView logo=tv("🧺  بقالة العنزي",21);logo.setTextColor(Color.WHITE);logo.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(logo,new LinearLayout.LayoutParams(0,62,1));TextView pt=tv(title,16);pt.setTextColor(Color.WHITE);bar.addView(pt);root.addView(bar);ScrollView sv=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(14,14,14,14);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));bottom=new LinearLayout(this);bottom.setGravity(Gravity.CENTER);bottom.setBackgroundColor(Color.WHITE);String[] ns={"الرئيسية","الحسابات","الفواتير","المخزون","التقارير"};for(String n:ns){Button b=button(n);b.setTextSize(12);b.setOnClickListener(v->navigate(n));bottom.addView(b,new LinearLayout.LayoutParams(0,64,1));}root.addView(bottom);setContentView(root);}
 void navigate(String n){if(n.equals("الرئيسية"))home();else if(n.equals("الحسابات"))customers();else if(n.equals("الفواتير"))invoice();else if(n.equals("المخزون"))inventory();else reports();}
 void home(){base("الرئيسية");TextView hero=tv("بقالة العنزي\nمرحباً بكم في بقالتكم المفضلة\nنظام الفواتير ودفتر الحسابات — يعمل محلياً بدون إنترنت",22);hero.setTextColor(Color.WHITE);hero.setGravity(Gravity.CENTER);hero.setPadding(20,28,20,28);hero.setBackgroundColor(GREEN);content.addView(hero);addSpace();addAction("🧾  إنشاء فاتورة مبيعات","الإجمالي ← الكمية ← الصنف، ثم حفظ ومشاركة",v->invoice());addAction("👥  العملاء والحسابات","كشف الحساب، عليه، له، الرصيد والمشاركة",v->customers());addAction("📦  المخزون","الأصناف والكميات والحد الأدنى",v->inventory());addAction("📊  التقارير والسجل","ملخص الفواتير والحركة",v->reports());}
 void addAction(String a,String sub,View.OnClickListener l){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);Button b=button(a);b.setTextSize(18);b.setTextColor(GREEN);b.setOnClickListener(l);c.addView(b);c.addView(tv(sub,13));content.addView(c);addSpace();}
 void addSpace(){Space s=new Space(this);content.addView(s,new LinearLayout.LayoutParams(1,8));}

 void invoice(){
  base("إنشاء فاتورة");EditText no=field("رقم الفاتورة");no.setText(String.valueOf(db.nextInvoice()));content.addView(no);EditText customer=field("اسم العميل");content.addView(customer);TextView h=tv("الإدخال: الإجمالي ثم الكمية ثم اسم الصنف — سعر الوحدة يُحسب تلقائياً",13);h.setTextColor(BLUE);content.addView(h);
  EditText lineTotal=field("الإجمالي");EditText qty=field("الكمية");qty.setText("1");EditText item=field("اسم الصنف");TextView unit=tv("سعر الوحدة: 0",14);unit.setTextColor(Color.GRAY);content.addView(lineTotal);content.addView(qty);content.addView(item);content.addView(unit);
  Button add=button("＋ إضافة الصنف");add.setTextColor(Color.WHITE);add.setBackgroundColor(GREEN);content.addView(add);TextView total=tv("الإجمالي: 0 ريال",24);total.setTextColor(GREEN);total.setTypeface(Typeface.DEFAULT,Typeface.BOLD);total.setGravity(Gravity.CENTER);total.setBackgroundColor(Color.rgb(255,247,218));content.addView(total);LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);content.addView(rows);final double[] sum={0};
  add.setOnClickListener(v->{try{String n=item.getText().toString().trim();double q=Double.parseDouble(qty.getText().toString()),t=Double.parseDouble(lineTotal.getText().toString());if(n.isEmpty()||q<=0||t<0)throw new Exception();double p=t/q;unit.setText("سعر الوحدة: "+fmt(p)+" ريال");sum[0]+=t;TextView r=tv(n+"  |  "+fmt(q)+"  |  "+fmt(p)+"  |  "+fmt(t),15);r.setTag(t);rows.addView(r);total.setText("الإجمالي: "+fmt(sum[0])+" ريال");item.setText("");qty.setText("1");lineTotal.setText("");item.requestFocus();}catch(Exception e){Toast.makeText(this,"أدخل الإجمالي والكمية واسم الصنف بشكل صحيح",Toast.LENGTH_SHORT).show();}});
  Button clear=button("مسح الكل");clear.setOnClickListener(v->{rows.removeAllViews();sum[0]=0;total.setText("الإجمالي: 0 ريال");});content.addView(clear);
  Button save=button("💾 حفظ الفاتورة");save.setTextColor(Color.WHITE);save.setBackgroundColor(GREEN);content.addView(save);
  save.setOnClickListener(v->{if(sum[0]<=0){Toast.makeText(this,"أضف صنفاً أولاً",Toast.LENGTH_SHORT).show();return;}String cn=customer.getText().toString().trim();long cid=cn.isEmpty()?-1:db.customer(cn);String date=db.now();long inv=db.addInvoice(no.getText().toString(),cn,sum[0],date);if(cid>0)db.addTransaction(cid,sum[0],"فاتورة مبيعات رقم "+no.getText(),1,date);String text=receiptText(no.getText().toString(),cn,rows,sum[0],cid);showShareDialog("تم حفظ الفاتورة","يمكنك الآن مشاركة الفاتورة كصورة إيصال 58mm أو كنص عبر واتساب",text);no.setText(String.valueOf(db.nextInvoice()));rows.removeAllViews();sum[0]=0;total.setText("الإجمالي: 0 ريال");});
  Button print=button("🖨 معاينة إيصال 58mm");print.setOnClickListener(v->thermalPreview(no.getText().toString(),customer.getText().toString(),rows,sum[0]));content.addView(print);
 }
 String receiptText(String no,String customer,LinearLayout rows,double total,long cid){StringBuilder s=new StringBuilder("بقالة العنزي\n");s.append("فاتورة رقم: ").append(no).append("\nالتاريخ: ").append(db.now()).append("\n");if(!customer.isEmpty())s.append("العميل: ").append(customer).append("\n");s.append("--------------------\n");for(int i=0;i<rows.getChildCount();i++)s.append(((TextView)rows.getChildAt(i)).getText()).append("\n");s.append("--------------------\nالإجمالي: ").append(fmt(total)).append(" ريال\n");if(cid>0){double bal=db.balance(cid);s.append(balanceText(bal)).append("\n");}s.append("شكراً لتعاملكم معنا");return s.toString();}
 String balanceText(double b){return b>0?"رصيد العميل عليه: "+fmt(b)+" ريال":b<0?"رصيد العميل له: "+fmt(Math.abs(b))+" ريال":"رصيد العميل: 0 ريال";}
 void showShareDialog(String title,String text,String receipt){new AlertDialog.Builder(this).setTitle(title).setMessage(text).setPositiveButton("واتساب", (d,w)->shareWhatsApp(receipt)).setNeutralButton("مشاركة النص", (d,w)->shareText(receipt)).setNegativeButton("إيصال 58mm", (d,w)->receiptImageDialog(receipt)).show();}
 void shareText(String s){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,s);startActivity(Intent.createChooser(i,"إرسال الفاتورة")); }
 void shareWhatsApp(String s){try{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.setPackage("com.whatsapp");i.putExtra(Intent.EXTRA_TEXT,s);startActivity(i);}catch(Exception e){shareText(s);}}
 void receiptImageDialog(String s){TextView v=tv(s,12);v.setTypeface(Typeface.MONOSPACE);v.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);new AlertDialog.Builder(this).setTitle("إيصال 58mm").setView(v).setPositiveButton("مشاركة الصورة", (d,w)->shareText(s)).setNegativeButton("إغلاق",null).show();}
 void thermalPreview(String no,String customer,LinearLayout rows,double total){String s=receiptText(no,customer,rows,total,customer.isEmpty()?-1:db.customer(customer));TextView v=tv(s,12);v.setTypeface(Typeface.MONOSPACE);v.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);new AlertDialog.Builder(this).setTitle("معاينة 58mm").setView(v).setPositiveButton("مشاركة", (d,w)->shareWhatsApp(s)).setNegativeButton("إغلاق",null).show();}
 String fmt(double x){return String.format(Locale.US,"%.2f",x).replace(".00","");}

 void customers(){base("العملاء والحسابات");EditText search=field("بحث بالاسم أو الهاتف");content.addView(search);EditText name=field("اسم العميل");EditText phone=field("رقم الهاتف");content.addView(name);content.addView(phone);Button add=button("＋ إضافة عميل");add.setTextColor(Color.WHITE);add.setBackgroundColor(GREEN);content.addView(add);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);Runnable refresh=()->{list.removeAllViews();Cursor c=db.customers(search.getText().toString());while(c.moveToNext()){long id=c.getLong(0);String n=c.getString(1),p=c.getString(2);double bal=db.balance(id);Button b=button(n+"\n"+(p.isEmpty()?"بدون رقم":p)+"  |  "+balanceText(bal));b.setGravity(Gravity.RIGHT);b.setOnClickListener(v->account(id,n));list.addView(b);}c.close();};add.setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty())return;db.addCustomer(n,phone.getText().toString().trim());name.setText("");phone.setText("");refresh.run();});search.setOnKeyListener((v,k,e)->{refresh.run();return false;});refresh.run();}
 void account(long id,String name){base("حساب العميل: "+name);TextView bal=tv(balanceText(db.balance(id)),23);bal.setTextColor(BLUE);content.addView(bal);EditText amount=field("المبلغ");EditText details=field("التفاصيل");content.addView(amount);content.addView(details);Button debit=button("عليه");debit.setTextColor(RED);Button credit=button("له / دفعة");credit.setTextColor(GREEN);content.addView(debit);content.addView(credit);Button share=button("📲 مشاركة كشف الحساب واتساب");share.setOnClickListener(v->shareWhatsApp(statement(id,name)));content.addView(share);LinearLayout history=new LinearLayout(this);history.setOrientation(LinearLayout.VERTICAL);content.addView(history);Runnable refresh=()->{history.removeAllViews();Cursor c=db.transactions(id);while(c.moveToNext()){double a=c.getDouble(3);TextView r=tv(c.getString(1)+"\n"+c.getString(2)+"\n"+(c.getInt(4)==1?"عليه":"له")+"  "+fmt(a)+" ريال",15);history.addView(r);}c.close();bal.setText(balanceText(db.balance(id)));};View.OnClickListener add=v->{try{double a=Double.parseDouble(amount.getText().toString());if(a<=0)throw new Exception();db.addTransaction(id,a,details.getText().toString(),v==debit?1:0,db.now());amount.setText("");details.setText("");refresh.run();}catch(Exception e){Toast.makeText(this,"أدخل المبلغ بشكل صحيح",Toast.LENGTH_SHORT).show();}};debit.setOnClickListener(add);credit.setOnClickListener(add);refresh.run();}
 String statement(long id,String name){StringBuilder s=new StringBuilder("بقالة العنزي\nكشف حساب العميل: ").append(name).append("\n");Cursor c=db.transactions(id);while(c.moveToNext())s.append(c.getString(1)).append(" | ").append(c.getString(2)).append(" | ").append(c.getInt(4)==1?"عليه":"له").append(": ").append(fmt(c.getDouble(3))).append(" ريال\n");c.close();s.append("--------------------\n").append(balanceText(db.balance(id)));return s.toString();}

 void inventory(){base("المخزون والأصناف");EditText name=field("اسم الصنف");EditText qty=field("الكمية");EditText min=field("الحد الأدنى");content.addView(name);content.addView(qty);content.addView(min);Button add=button("＋ حفظ الصنف");add.setTextColor(Color.WHITE);add.setBackgroundColor(GREEN);content.addView(add);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);Runnable refresh=()->{list.removeAllViews();Cursor c=db.items();while(c.moveToNext())list.addView(tv(c.getString(1)+"  |  الكمية: "+fmt(c.getDouble(2))+"  |  الحد الأدنى: "+fmt(c.getDouble(3)),16));c.close();};add.setOnClickListener(v->{try{db.addItem(name.getText().toString().trim(),Double.parseDouble(qty.getText().toString()),Double.parseDouble(min.getText().toString()));name.setText("");qty.setText("");min.setText("");refresh.run();}catch(Exception e){Toast.makeText(this,"أدخل بيانات الصنف",Toast.LENGTH_SHORT).show();}});refresh.run();}
 void reports(){base("التقارير والسجل");content.addView(tv("ملخص المبيعات",20));content.addView(tv("عدد الفواتير: "+db.invoiceCount()+"\nإجمالي المبيعات: "+fmt(db.sales())+" ريال\nعدد العملاء: "+db.customerCount(),19));Cursor c=db.invoices();while(c.moveToNext())content.addView(tv("فاتورة "+c.getString(1)+" | "+c.getString(2)+" | "+fmt(c.getDouble(4))+" ريال\n"+c.getString(3),15));c.close();}
 static class DB extends SQLiteOpenHelper{DB(Context c){super(c,"enezi.db",null,2);}public void onCreate(SQLiteDatabase d){create(d);}void create(SQLiteDatabase d){d.execSQL("CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT)");d.execSQL("CREATE TABLE invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,no TEXT,customer TEXT,total REAL,date TEXT)");d.execSQL("CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER,amount REAL,details TEXT,type INTEGER,date TEXT)");d.execSQL("CREATE TABLE items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,qty REAL,min_qty REAL)");}public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2){try{d.execSQL("ALTER TABLE invoices ADD COLUMN date TEXT");}catch(Exception ignored){}}}String now(){return new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date());}long customer(String n){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM customers WHERE name=?",new String[]{n});if(c.moveToFirst()){long x=c.getLong(0);c.close();return x;}c.close();ContentValues v=new ContentValues();v.put("name",n);return getWritableDatabase().insert("customers",null,v);}void addCustomer(String n,String p){ContentValues v=new ContentValues();v.put("name",n);v.put("phone",p);getWritableDatabase().insert("customers",null,v);}long addInvoice(String no,String c,double t,String date){ContentValues v=new ContentValues();v.put("no",no);v.put("customer",c);v.put("total",t);v.put("date",date);return getWritableDatabase().insert("invoices",null,v);}void addTransaction(long id,double a,String d,int type,String date){if(id<1)return;ContentValues v=new ContentValues();v.put("customer_id",id);v.put("amount",a);v.put("details",d);v.put("type",type);v.put("date",date);getWritableDatabase().insert("transactions",null,v);}double balance(long id){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(CASE WHEN type=1 THEN amount ELSE -amount END),0) FROM transactions WHERE customer_id=?",new String[]{String.valueOf(id)});double x=c.moveToFirst()?c.getDouble(0):0;c.close();return x;}Cursor customers(String q){return getReadableDatabase().rawQuery("SELECT id,name,COALESCE(phone,'') FROM customers WHERE name LIKE ? OR phone LIKE ? ORDER BY name",new String[]{"%"+q+"%","%"+q+"%"});}Cursor transactions(long id){return getReadableDatabase().rawQuery("SELECT id,date,details,amount,type FROM transactions WHERE customer_id=? ORDER BY id DESC",new String[]{String.valueOf(id)});}Cursor items(){return getReadableDatabase().rawQuery("SELECT id,name,qty,min_qty FROM items ORDER BY name",null);}void addItem(String n,double q,double m){if(n.isEmpty())throw new IllegalArgumentException();ContentValues v=new ContentValues();v.put("name",n);v.put("qty",q);v.put("min_qty",m);getWritableDatabase().insert("items",null,v);}Cursor invoices(){return getReadableDatabase().rawQuery("SELECT id,no,customer,total,date FROM invoices ORDER BY id DESC LIMIT 100",null);}int invoiceCount(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM invoices",null);int x=c.moveToFirst()?c.getInt(0):0;c.close();return x;}int customerCount(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM customers",null);int x=c.moveToFirst()?c.getInt(0):0;c.close();return x;}double sales(){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(total),0) FROM invoices",null);double x=c.moveToFirst()?c.getDouble(0):0;c.close();return x;}int nextInvoice(){return invoiceCount()+1;}}
}
